import {ROLES,ACTORS,definitionIssues,finances,projectHealth,staffingText,invoiceTotals,getInvoiceForMonth,monthsBetween,daysInProjectMonth,plannedMonth,sum} from './domain.js';
export const h=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
export const euro=v=>v===null?'À confirmer':new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',minimumFractionDigits:0,maximumFractionDigits:2}).format(v);
export const dec=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(v);
export const date=v=>v?new Date(v+'T12:00:00Z').toLocaleDateString('fr-FR'):'À renseigner';
export const month=v=>v?new Date(v+'-01T12:00:00Z').toLocaleDateString('fr-FR',{month:'long',year:'numeric'}):'';
const btn=(text,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const tag=(text,color='')=>`<span class="tag ${color}">${h(text)}</span>`;
const alert=(text,kind='info')=>`<div class="alert ${kind}"><div>${text}</div></div>`;
const metric=(label,value,detail='',accent='')=>`<div class="metric ${accent}"><div class="label">${label}</div><div class="number ${value==='À confirmer'?'word':''}">${value}</div><div class="detail">${detail}</div></div>`;
const heading=(title,text,actions='')=>`<div class="heading"><div><h1>${title}</h1><p>${text}</p></div><div class="heading-actions">${actions}</div></div>`;
const panel=(title,subtitle,body,actions='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions}</div>${body}</section>`;
function input(label,name,value,type='text',attr=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${h(value)}" ${attr}></label>`;}
function area(label,name,value,attr=''){return `<label class="field"><span>${label}</span><textarea name="${name}" ${attr}>${h(value)}</textarea></label>`;}
function select(label,name,value,items){return `<label class="field"><span>${label}</span><select name="${name}">${items.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select></label>`;}
export function login(){return `<main class="login"><section class="login-story"><div class="brand"><span class="logo">C</span> Cockpit CDS</div><span class="tag" style="margin-top:60px">PO · Projets · Factures</span><h1>Un budget.<br>Des projets.<br>Une trajectoire claire.</h1><p>Initialiser le portefeuille, décrire le dispositif, puis rapprocher chaque facture des jours réellement ventilés.</p><div class="journey-list"><div><b>Accor</b> Saisir le PO et ses projets</div><div><b>Fournisseur</b> Ventiler et éditer la facture</div><div><b>Owner du PO</b> Contrôler et valider</div></div><p class="small">POC illustratif · Données enregistrées dans ce navigateur. Les profils simulent les droits d’accès.</p></section><section class="login-choice"><div class="eyebrow muted">Votre espace de travail</div><h2 style="margin-top:12px">Choisir un profil</h2><p class="muted">Parcourez le même cockpit avec trois points de vue.</p>${[['laurent','LA','Laurent','Accor · Owner du PO','Initialiser le cockpit, suivre le budget et valider les factures.'],['jennifer','JE','Jennifer','Accor · Pilotage','Initialiser le cockpit, ajuster le dispositif et suivre la trajectoire.'],['lassaad','LS','Lassaad','Fournisseur · Responsable CDS','Consulter les enveloppes, ventiler les jours et préparer les factures.']].map(([id,initials,name,title,desc])=>`<article class="persona-card"><span class="avatar ${id==='lassaad'?'gold':'teal'}">${initials}</span><div><h3>${name} <span class="muted small">${title}</span></h3><p>${desc}</p>${btn('Entrer dans cet espace','login',`data-id="${id}"`,'primary')}</div></article>`).join('')}</section></main>`;}
export function shell(store,who,tab,body,shared=false){const c=store.cockpits.find(c=>c.id===store.activeId),isAccor=who!=='lassaad';const nav=[['budget','Cockpit budgétaire'],...(isAccor?[['setup','Initialisation']]:[['allocation','Ventilation mensuelle']]),...(who==='laurent'||who==='lassaad'?[['invoices',who==='laurent'?'Factures reçues':'Mes factures']]:[]),['guide','Mode d’emploi']];return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">C</span>Cockpit CDS</div><div class="nav-label">PORTEFEUILLE PROJETS</div><nav class="nav" aria-label="Navigation principale">${nav.map(([id,label])=>`<button type="button" data-action="nav" data-id="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="side-po">${h(c.poRef||'Nouveau PO')}<strong>${euro(c.budget)}</strong>${tag(c.status==='active'?'Cockpit actif':'Brouillon',c.status==='active'?'green':'amber')}</div><div class="side-bottom"><div class="name">${ACTORS[who]}</div><div class="small">${who==='lassaad'?'Responsable CDS':'Accor · '+(who==='laurent'?'Owner du PO':'Pilotage')}</div>${shared?'':btn('Changer de profil','logout')}</div></aside><div class="workspace"><header class="topbar"><div class="inline"><label class="sr-only" for="cockpit-switch">Portefeuille actif</label><select id="cockpit-switch" data-change="cockpit">${store.cockpits.map(x=>`<option value="${h(x.id)}" ${c.id===x.id?'selected':''}>${h(x.name||'Nouveau cockpit')} · ${h(x.poRef||'PO à saisir')}</option>`).join('')}</select>${isAccor?btn('Nouveau PO','new'):''}</div><div class="inline"><span class="demo-pill">${shared?'PO partagé · '+ACTORS[who]:'POC · Données locales'}</span>${shared?'':'<button class="btn mobile-profile" data-action="logout">'+ACTORS[who]+'</button>'}</div></header><main class="content">${c.demo?alert('<strong>Exemple à confirmer</strong>Budgets issus du scénario initial ; dates et dispositifs de démonstration. La transcription ne fixe pas de calendrier définitif.'):''}${body}<p class="subtle">${shared?'Saisies partagées. Actualisez la page pour retrouver les dernières mises à jour. Montants HT.':'Simulation locale : aucun email, paiement ou échange réel avec Jira. Montants HT. Sauvegardez vos données avec l’export JSON.'}</p></main></div></div>`;}
function projectTable(c,rows,unknown){return `<div class="table-wrap"><table class="project-table"><thead><tr><th>Projet</th><th>Dispositif prévu (ETP)</th><th>Début</th><th>Fin</th><th class="num">Budget initial</th><th class="num">Consommé validé</th><th class="num">Restant</th><th class="num">Forecast à terminaison</th><th>Prévision</th></tr></thead><tbody>${rows.map(p=>{const s=projectHealth(p,unknown>0);return `<tr><td><button class="link-btn project-link" data-action="project" data-id="${h(p.id)}">${h(p.name||'À nommer')}</button><div class="muted small">${h(p.category)}</div></td><td class="staff-cell">${h(p.staffing)}</td><td class="date">${date(p.start)}</td><td class="date">${date(p.end)}</td><td class="num">${euro(p.budget)}</td><td class="num">${euro(p.actual)}</td><td class="num">${euro(p.remaining)}</td><td class="num">${euro(p.forecast)}</td><td>${tag(s.label,s.color)}</td></tr>`;}).join('')}</tbody></table></div>`;}
export function budget(c,who){const f=finances(c),s=projectHealth({actual:f.actual,forecast:f.forecast,budget:c.budget},f.unknown>0);return heading('Cockpit budgétaire',`${h(c.name||'Portefeuille à initialiser')} · PO ${h(c.poRef||'à saisir')} · Arrêté à fin ${month(c.reportMonth)}`,btn('Exporter les projets CSV','csv')+btn('Sauvegarde JSON','backup'))+`<div class="steps"><div class="step ${c.status==='active'?'done':''}"><b>1</b>Initialiser le PO</div><div class="step ${Object.keys(c.expenses).length?'done':''}"><b>2</b>Ventiler les jours</div><div class="step ${c.invoices.some(i=>i.status==='validated')?'done':''}"><b>3</b>Valider la facture</div></div>`+(c.status==='draft'?alert(`<strong>Le cockpit est en brouillon</strong>${who==='lassaad'?'Laurent ou Jennifer doit confirmer le paramétrage avant la première ventilation.':'Vérifiez les hypothèses dans Initialisation, puis activez le cockpit.'}`):'')+`<div class="summary">${metric('Budget initial du PO',euro(f.budget),`${c.projects.length} projets · ${date(c.start)} au ${date(c.end)}`)}${metric('Consommé validé',euro(f.actual),'Reprise initiale + factures validées par Laurent')}${metric('Budget restant',euro(f.remaining),'Budget initial − consommé validé')}${metric('Forecast à terminaison',euro(f.forecast),tag(s.label,s.color),'accent')}</div>`+(f.unknown?alert(`<strong>${euro(f.unknown)} non affectés à un projet</strong>Ces jours restent visibles dans le forecast global. L’envoi de la facture est bloqué tant qu’ils ne sont pas affectés.`):'')+(f.missingMonths.length?alert(`<strong>Ventilations manquantes : ${f.missingMonths.map(month).join(', ')}</strong>Le forecast conserve le coût du dispositif prévu pour ces mois ; ils ne sont pas considérés comme gratuits.`):'')+(f.provisional?alert(`${euro(f.provisional)} de jours ventilés en attente de validation de facture. Ils sont inclus dans le forecast, pas dans le consommé validé.`):'')+panel('Portefeuille projets','Le dispositif et les dates encadrent le coût prévisionnel de chaque projet.',projectTable(c,f.rows,f.unknown)) + panel('Comprendre le forecast','Une projection fondée sur les périodes et les profils, actualisée avec les factures.',`<div class="panel-body explanation"><p><b>Forecast</b> = consommé validé + jours ventilés non encore validés + coût du dispositif sur les mois non renseignés et les mois à venir.</p><p><b>Dispositif</b> en équivalents temps plein. Exemple : 0,5 TL + 3 Dev + 1 QA. Coût = ETP × TJM × jours facturables dans la période.</p><p><b>Calendrier</b> : ${dec(c.monthlyDays)} jours par mois complet, prorata des jours de semaine pour un mois partiel, sans calendrier de jours fériés. La projection s’arrête à la date de fin du projet.</p><p><b>Seuils</b> : vert &lt; 95 % du budget ; orange de 95 à 100 % ; rouge au-delà. Une ventilation non affectée suspend le statut vert.</p></div>`);}
export function setup(c,shared=false){return heading('Initialiser le cockpit','Laurent et Jennifer définissent le PO, le budget de chaque projet, ses dates et son dispositif.')+`<form id="setup-form"><div id="setup-feedback" role="status"></div>`+panel('Le PO et ses responsables','Un PO correspond à un portefeuille de projets.',`<div class="panel-body form-grid">${input('Nom du portefeuille','name',c.name)}${input('Référence du PO','poRef',c.poRef,'text',shared?'readonly':'')}${input('Exercice','year',c.year,'number','min="2000" max="2100" step="1"')}${input('Budget total du PO (€ HT)','budget',c.budget,'number','min="0" step="0.01"')}${input('Date de début du PO','start',c.start,'date')}${input('Date de fin du PO','end',c.end,'date')}${input('Arrêté du cockpit (fin de mois)','reportMonth',c.reportMonth,'month')}${input('Jours facturables par mois / ETP','monthlyDays',c.monthlyDays,'number','min="0.5" max="31" step="0.5"')}${input('Owner du PO','owner',c.owner)}${input('Copilote Accor','coOwner',c.coOwner)}${input('Responsable fournisseur','supplier',c.supplier)}${input('Reprise du consommé à fin de mois (optionnel)','openingMonth',c.openingMonth,'month')}<p class="field-hint full">Pour reprendre un suivi existant, saisissez un mois de reprise et le consommé déjà validé dans chaque projet. Les nouvelles ventilations commenceront le mois suivant.</p></div>`)+panel('TJM contractuels','Valeurs de démonstration modifiables, à confirmer avant activation.',`<div class="panel-body rate-grid">${ROLES.map(r=>input(`${r.short} (€ / jour)`,`rate-${r.id}`,c.rates[r.id],'number','min="0" step="0.01"')).join('')}</div>`)+panel('Répartir le PO en projets','Saisir des capacités par profil. Le total des budgets projets doit égaler le montant du PO.',`<div id="split-summary" class="split-summary"></div><div class="panel-body project-forms">${c.projects.map((p,i)=>projectForm(p,i,shared)).join('')}</div><div class="footer-action"><p>Une phase d’hypercare peut être ajoutée comme une ligne distincte avec ses propres dates et son dispositif.</p>${btn('Ajouter un projet','add-project')}</div>`)+`<div class="sticky-actions"><div><strong>${c.status==='active'?'Cockpit actif':'Brouillon'}</strong><p class="small muted">${c.status==='active'?'Les modifications restent contrôlées pour préserver l’historique.':'Vous pouvez enregistrer une saisie incomplète en brouillon.'}</p></div><div class="inline"><button class="btn" type="submit" name="intent" value="save">${c.status==='active'?'Enregistrer les modifications':'Enregistrer le brouillon'}</button>${c.status==='draft'?'<button class="btn teal" type="submit" name="intent" value="activate">Confirmer et activer le cockpit</button>':''}</div></div></form>`;}
function projectForm(p,i,shared){return `<fieldset class="project-form" data-project="${h(p.id)}"><legend>Projet ${i+1} · ${h(p.name||'À nommer')}</legend><div class="form-grid">${input('Nom du projet','p-name',p.name)}${select('Nature du projet','p-category',p.category,['Build','Run','Hypercare'].map(v=>[v,v]))}${input('Budget initial du projet (€ HT)','p-budget',p.budget,'number','min="0" step="0.01"')}${input('Consommé déjà validé à la reprise (€ HT)','p-openingValidated',p.openingValidated,'number','min="0" step="0.01"')}${input('Date de début','p-start',p.start,'date')}${input('Date de fin','p-end',p.end,'date')}</div><div class="device-heading"><h3>Dispositif prévu</h3><span class="muted small">ETP par pas de 0,5 · ${h(staffingText(p.device))}</span></div><div class="rate-grid">${ROLES.map(r=>input(`${r.short} (ETP)`,`p-device-${r.id}`,p.device[r.id],'number','min="0" step="0.5"')).join('')}</div>${shared?`<div class="epic-links"><strong>Epics Jira OP</strong><p data-epic-label>${h(p.epics||'Aucun epic rattaché')}</p><input type="hidden" name="p-epics" value="${h(p.epics)}">${btn('Choisir les epics Jira OP','jira-epics',`data-id="${h(p.id)}"`)}</div>`:`<div class="epic-links">${input('Epics Jira (séparées par une virgule)','p-epics',p.epics)}</div>`}<details class="optional-fields"><summary>Informations complémentaires · story points, notes</summary><div class="form-grid">${input('Story points prévus (optionnel)','p-pointsPlanned',p.pointsPlanned,'number','min="0" step="any"')}${input('Story points livrés (optionnel)','p-pointsDelivered',p.pointsDelivered,'number','min="0" step="any"')}${area('Hypothèses et notes','p-notes',p.notes)}</div><p class="field-hint">Les story points restent un indicateur de livraison ; ils ne sont pas convertis en jours ou en euros.</p></details><div class="project-form-footer">${btn('Retirer ce projet','remove-project',`data-id="${h(p.id)}"`,'danger')}</div></fieldset>`;}
export function allocation(c,m){const i=getInvoiceForMonth(c,m),s=c.expenses[m],locked=!!i;const rows=[...c.projects.map(p=>({id:p.id,name:p.name,staff:staffingText(p.device),start:p.start,end:p.end})),{id:'unknown',name:'Non affecté',staff:'À rapprocher d’un projet',start:'',end:''}];return heading('Ventilation mensuelle','Lassaad renseigne les jours réalisés par projet et par profil, puis prépare la facture.')+(c.status!=='active'?alert('Le cockpit doit être activé par Laurent ou Jennifer. Vous pouvez consulter le budget et le paramétrage prévu.'):'')+`<div class="context-switch"><label for="allocation-month">Mois de ventilation</label><select id="allocation-month" data-change="month">${monthsBetween(c.start,c.end).filter(x=>!c.openingMonth||x>c.openingMonth).map(x=>`<option value="${x}" ${x===m?'selected':''}>${month(x)}</option>`).join('')}</select>${tag(i?status(i.status):s?'Ventilation enregistrée':'À renseigner',i?.status==='validated'?'green':'amber')}</div>`+(i?alert(`<strong>Ventilation liée à ${h(i.number)}</strong>${['draft','returned'].includes(i.status)?'Pour modifier les jours ventilés, utilisez « Reprendre la ventilation ». La facture actuelle sera conservée comme annulée.':'La ventilation est verrouillée. Laurent doit retourner une facture envoyée avant modification.'}`):'')+`<form id="allocation-form" data-month="${h(m)}"><fieldset ${locked||c.status!=='active'?'disabled':''} class="plain-fieldset">`+panel('Jours réalisés','Imputation manuelle par pas de 0,5 jour. Les cellules hors période projet sont désactivées.',`<div class="toolbar"><p class="small muted">Le dispositif prévu sert de repère, pas de preuve de jours travaillés.</p>${btn('Préremplir depuis le dispositif prévu','prefill')}</div><div class="table-wrap"><table class="allocation-table"><thead><tr><th>Projet / dispositif</th><th>Période</th>${ROLES.map(r=>`<th class="num">${r.short} (j)</th>`).join('')}<th class="num">Valorisation</th></tr></thead><tbody>${rows.map(p=>{const unknown=p.id==='unknown',active=unknown||daysInProjectMonth(p,m,c.monthlyDays)>0;return `<tr data-allocation="${h(p.id)}" class="${unknown?'unallocated-row':''}"><td><strong>${h(p.name)}</strong><div class="small muted staff-cell">${h(p.staff)}</div>${unknown?`<label class="field small"><span>Motif</span><input name="unknown-note" value="${h(s?.rows.find(r=>r.projectId===null)?.note||'')}" placeholder="Ex. epic sans rattachement"></label>`:''}</td><td class="date small">${unknown?'À affecter':`${date(p.start)}<br>${date(p.end)}`}</td>${ROLES.map(r=>{const val=s?.rows.find(l=>(l.projectId||'unknown')===p.id&&l.roleId===r.id)?.days||0;return `<td><input aria-label="Jours ${h(r.short)} pour ${h(p.name)}" class="day-input" data-role="${r.id}" type="number" min="0" step="0.5" value="${val}" ${active?'':'disabled'}></td>`;}).join('')}<td class="num" data-row-total>0 €</td></tr>`;}).join('')}</tbody><tfoot><tr class="total-row"><td colspan="7">Total valorisé · TJM contractuels</td><td class="num" id="allocation-total">0 €</td></tr></tfoot></table></div><div class="panel-body"><label class="check-line"><input type="checkbox" name="zeroConfirmed" ${s?.zeroConfirmed?'checked':''}> Je confirme explicitement que ce mois ne comporte aucun jour à facturer.</label><div id="capacity-feedback" class="field-hint"></div></div>`)+`</fieldset><div class="footer-action allocation-footer"><p>La ventilation alimente le forecast. Le consommé sera reconnu après validation de la facture par Laurent.</p><div class="inline">${!locked?'<button class="btn primary" type="submit" '+(c.status!=='active'?'disabled':'')+'>Enregistrer la ventilation</button>':''}${s&&!i&&s.rows.length?btn('Créer la facture','create-invoice',`data-month="${h(m)}"`,'teal'):''}${i?btn('Ouvrir la facture','invoice',`data-id="${h(i.id)}"`):''}${i&&['draft','returned'].includes(i.status)?btn('Reprendre la ventilation','revise',`data-month="${h(m)}"`):''}</div></div></form>`;}
export const status=s=>({draft:'Brouillon',sent:'À valider',validated:'Validée',returned:'Retournée',cancelled:'Annulée'}[s]||s);
export function invoices(c,who){const rows=c.invoices.filter(i=>who==='lassaad'||i.status!=='draft'&&i.status!=='cancelled');return heading(who==='laurent'?'Factures mensuelles reçues':'Mes factures',who==='laurent'?'Contrôler le rapprochement et valider le montant qui sera imputé au portefeuille.':'La facture est éditable jusqu’à l’envoi. Elle est ensuite contrôlée par Laurent.')+panel('Rapprochement mensuel','Attendu = ventilation enregistrée × TJM contractuels. Écart = facturé − attendu.',rows.length?`<div class="table-wrap"><table><thead><tr><th>Facture</th><th>Mois</th><th class="num">Attendu</th><th class="num">Facturé</th><th class="num">Écart</th><th>Contrôle</th><th>Statut</th><th></th></tr></thead><tbody>${[...rows].reverse().map(i=>{const t=invoiceTotals(i);return `<tr><td>${h(i.number)}</td><td>${month(i.month)}</td><td class="num">${euro(t.expected)}</td><td class="num">${euro(t.billed)}</td><td class="num ${t.delta?'text-red':''}">${t.delta>0?'+':''}${euro(t.delta)}</td><td>${tag(t.delta?'Écart à vérifier':'Conforme',t.delta?'amber':'green')}</td><td>${tag(status(i.status),i.status==='validated'?'green':i.status==='cancelled'?'unknown':'amber')}</td><td>${btn('Consulter','invoice',`data-id="${h(i.id)}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty"><h3>Aucune facture ${who==='laurent'?'reçue':'créée'}</h3><p>${who==='laurent'?'Les factures apparaîtront ici après leur envoi par Lassaad.':'Enregistrez d’abord une ventilation mensuelle pour générer la facture.'}</p></div>`);}
export function invoiceDetail(c,i,who){const t=invoiceTotals(i),editable=who==='lassaad'&&['draft','returned'].includes(i.status);return `<div class="dialog-header"><div><div class="eyebrow muted">Facture mensuelle · Simulation</div><h2>${h(i.number)}</h2></div><button class="close" data-action="close" aria-label="Fermer">×</button></div><div class="body"><div class="inline invoice-state">${tag(status(i.status),i.status==='validated'?'green':'amber')}<span class="muted small">PO ${h(i.poRef)} · ${month(i.month)} · Révision ${i.revision}</span></div>${i.reviewNote?alert(`<strong>Commentaire de Laurent</strong>${h(i.reviewNote)}`,i.status==='returned'?'':'info'):''}<form id="invoice-form" data-id="${h(i.id)}"><fieldset class="plain-fieldset" ${editable?'':'disabled'}><div class="form-grid invoice-fields">${input('Numéro de facture','number',i.number)}${input('Date de facture','date',i.date,'date')}</div><div class="table-wrap"><table><thead><tr><th>Projet / profil</th><th class="num">Jours attendus</th><th class="num">TJM attendu</th><th class="num">Jours facturés</th><th class="num">TJM facturé</th><th class="num">Total facturé</th></tr></thead><tbody>${i.lines.map(l=>`<tr data-invoice-line="${h(l.id)}"><td>${h(l.projectName)}<br><span class="small muted">${h(ROLES.find(r=>r.id===l.roleId)?.short)}</span></td><td class="num">${dec(l.expectedDays)}</td><td class="num">${euro(l.expectedRate)}</td><td><input aria-label="Jours facturés ${h(l.projectName)} ${h(l.roleId)}" name="billedDays" type="number" min="0" step="0.5" value="${l.billedDays}" class="day-input"></td><td><input aria-label="TJM facturé ${h(l.projectName)} ${h(l.roleId)}" name="billedRate" type="number" min="0" step="0.01" value="${l.billedRate}" class="rate-input"></td><td class="num" data-line-total>${euro(l.billedDays*l.billedRate)}</td></tr>`).join('')}</tbody></table></div><div class="summary invoice-summary">${metric('Attendu',euro(t.expected),'Jours ventilés × TJM contractuels')}${metric('Facturé',`<span id="billed-total">${euro(t.billed)}</span>`,'Montant de la facture')}${metric('Écart signé',`<span id="invoice-delta">${t.delta>0?'+':''}${euro(t.delta)}</span>`,'Facturé − attendu')}</div><div class="panel-body">${area('Explication fournisseur (obligatoire si écart)','supplierNote',i.supplierNote)}</div></fieldset><div id="invoice-match" class="alert ${t.delta?'':'success'}">${t.delta?'Écart à vérifier':'Conforme à la ventilation'}</div><div class="inline">${editable?'<button class="btn" type="submit" name="intent" value="save">Enregistrer la facture</button><button class="btn teal" type="submit" name="intent" value="send">Enregistrer et envoyer à Laurent</button>':''}${btn('Exporter la facture HTML','download-invoice',`data-id="${h(i.id)}"`)}</div></form>${who==='laurent'&&i.status==='sent'?`<form id="review-form" data-id="${h(i.id)}" class="review-form">${area('Commentaire de contrôle / motif de retour','reviewNote','')}<p class="field-hint">Une justification est obligatoire pour accepter un écart ou retourner la facture.</p><div class="inline"><button class="btn danger" type="submit" name="intent" value="return">Retourner à Lassaad</button><button class="btn teal" type="submit" name="intent" value="validate">Valider et imputer au budget</button></div></form>`:''}<p class="subtle">La facture est transmise dans le cockpit. La facture exportée est un document de démonstration.</p></div>`;}
export function projectDetail(c,p){const f=finances(c).rows.find(r=>r.id===p.id),s=projectHealth(f);return `<div class="dialog-header"><div><div class="eyebrow muted">Détail du projet</div><h2>${h(p.name)}</h2></div><button class="close" data-action="close" aria-label="Fermer">×</button></div><div class="body"><p><b>${h(staffingText(p.device))}</b> · ${date(p.start)} au ${date(p.end)} · ${tag(s.label,s.color)}</p><div class="summary">${metric('Budget',euro(p.budget))}${metric('Consommé validé',euro(f.actual))}${metric('Restant',euro(f.remaining))}${metric('Forecast',euro(f.forecast))}</div><div class="table-wrap"><table><thead><tr><th>Mois</th><th class="num">Coût du dispositif prévu</th><th class="num">Jours ventilés</th><th class="num">Valorisation ventilée</th><th>Facture</th></tr></thead><tbody>${monthsBetween(p.start,p.end).map(m=>{const rows=c.expenses[m]?.rows.filter(r=>r.projectId===p.id)||[],i=getInvoiceForMonth(c,m);return `<tr><td>${month(m)}</td><td class="num">${euro(plannedMonth(c,p,m))}</td><td class="num">${c.expenses[m]?dec(sum(rows.map(r=>r.days))):'À saisir'}</td><td class="num">${c.expenses[m]?euro(sum(rows.map(r=>r.amount))):'À saisir'}</td><td>${i?tag(status(i.status),i.status==='validated'?'green':'amber'):'Aucune'}</td></tr>`;}).join('')}</tbody></table></div><div class="explanation"><p><b>Epics Jira :</b> ${h(p.epics||'Rattachement manuel à renseigner')}</p><p><b>Story points :</b> ${p.pointsDelivered===null?'Non renseignés':dec(p.pointsDelivered)} livrés / ${p.pointsPlanned===null?'non renseignés':dec(p.pointsPlanned)} prévus. Sans conversion financière.</p><p><b>Hypothèses :</b> ${h(p.notes||'Aucune note')}</p></div></div>`;}
export function guide(c,shared=false){return heading('Un démarrage volontairement manuel','Un parcours financier simple, prêt à être présenté à Product et Tech.')+panel('Le parcours en trois temps','Les profils donnent accès à des actions différentes.',`<div class="panel-body rules-grid"><article><h3>1. Laurent / Jennifer</h3><p>Créer un cockpit, saisir le PO, répartir tout le budget dans les projets. Renseigner le début, la fin, les ETP et les TJM. Vérifier les hypothèses puis activer.</p></article><article><h3>2. Lassaad</h3><p>Chaque mois, ventiler les jours réalisés par projet et profil. Les jours sans rattachement restent « Non affecté ». Enregistrer, créer et éditer la facture, expliquer les écarts et l’envoyer.</p></article><article><h3>3. Laurent</h3><p>Consulter les factures reçues, comparer l’attendu au facturé, retourner avec un motif ou valider. La facture validée alimente le consommé une seule fois.</p></article><article><h3>Le cockpit partagé</h3><p>Laurent, Jennifer et Lassaad voient les budgets, les dispositifs et les dates. Le forecast s’arrête à chaque fin de projet. Jennifer conserve une vue de pilotage sans onglet factures.</p></article></div>`)+panel('Cadre du POC','Saisie et navigation illustratives.',`<div class="panel-body explanation"><p>${shared?'Votre accès individuel détermine vos droits. Les saisies validées sont partagées. Actualisez la page pour retrouver les dernières mises à jour. Le transfert de facture a lieu dans le cockpit.':'Les profils ne constituent pas une authentification. Les données sont conservées dans le navigateur et chaque ordinateur a sa propre démo. L’envoi de factures est simulé.'}</p><p>L’intégration Jira et le contrôle nominatif des CRA viendront ensuite. Le périmètre actuel permet d’abord de tester le paramétrage financier et le rapprochement.</p><p>Les données de démonstration ne valent pas engagement. Les dates de la transcription restent à confirmer. </p></div>`)+panel('Historique local','Dernières opérations du portefeuille.',`<div class="panel-body">${c.audit.length?c.audit.slice(0,30).map(a=>`<div class="audit"><b>${h(a.who)}</b><p>${h(a.action)}</p><time>${h(new Date(a.at).toLocaleString('fr-FR'))}</time></div>`).join(''):'Aucune opération enregistrée.'}</div>`);}
export function invoiceDocument(c,i){const t=invoiceTotals(i);return `<!doctype html><html lang="fr"><meta charset="utf-8"><title>${h(i.number)}</title><style>body{font:16px Arial;color:#14243d;margin:40px;line-height:1.5}h1{font-size:28px}table{border-collapse:collapse;width:100%;margin:28px 0}td,th{padding:12px;border-bottom:1px solid #ccd3de;text-align:left}.num{text-align:right}.notice{background:#fff4d9;padding:14px}@media print{button{display:none}}</style><h1>Facture mensuelle · Démonstration</h1><p class="notice">Document illustratif, sans valeur de facture fiscale. Aucun envoi réel.</p><p><b>${h(i.number)}</b> · ${date(i.date)} · ${h(status(i.status))}</p><p>Portefeuille : ${h(i.portfolioName)}<br>PO : ${h(i.poRef)}<br>Période : ${month(i.month)}<br>Fournisseur : ${h(c.supplier)} · Destinataire : ${h(c.owner)}</p><table><thead><tr><th>Projet</th><th>Profil</th><th class="num">Jours</th><th class="num">TJM</th><th class="num">Montant HT</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td>${h(l.projectName)}</td><td>${h(ROLES.find(r=>r.id===l.roleId)?.short)}</td><td class="num">${dec(l.billedDays)}</td><td class="num">${euro(l.billedRate)}</td><td class="num">${euro(l.billedDays*l.billedRate)}</td></tr>`).join('')}</tbody></table><p><b>Attendu : ${euro(t.expected)} · Facturé HT : ${euro(t.billed)} · Écart : ${t.delta>0?'+':''}${euro(t.delta)}</b></p><p>Explication fournisseur : ${h(i.supplierNote||'Aucun écart signalé')}</p><p>Contrôle Accor : ${h(i.reviewNote||'Aucun commentaire')}</p></html>`;}
